with feeders as (
    select
        md5(upper('HUB_RISK_OBJECT|' || (HUB_RISK_OBJECT_BK__LOAN_ACC_NUMBER))) as HUB_RISK_OBJECT_HK
        , 'LOAN' as INTEREST_TYPE
        , coalesce(nullif(trim(BANK_NAME), ''), '') as INTEREST_HOLDER_REFERENCE
        , LOAN_PERIOD as LOAN_TENOR
        , OTHER_LOAN_TYPE as OTHER_LOAN_TYPE_DESCRIPTION
        , 'BA_CCP_SUB_MATER_DTLS' as RECORD_SOURCE
        , 'opus_health_delta3' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_ba_ccp_sub_mater_dtls') }}
    where (nullif('LOANACC:' || nullif(trim(LOAN_ACC_NUMBER),''), 'LOANACC:')) is not null
),

resolved as (
    select
        HUB_RISK_OBJECT_HK,
        INTEREST_TYPE,
        INTEREST_HOLDER_REFERENCE,
        max(case when SOURCE_RUN = 'opus_health_delta3' then LOAN_TENOR end) as LOAN_TENOR,
        max(case when SOURCE_RUN = 'opus_health_delta3' then OTHER_LOAN_TYPE_DESCRIPTION end) as OTHER_LOAN_TYPE_DESCRIPTION,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_RISK_OBJECT_HK, INTEREST_TYPE, INTEREST_HOLDER_REFERENCE
),

hashed as (
