        *,
        case when INTEREST_TYPE is not null or INTEREST_HOLDER_REFERENCE is not null or LOAN_TENOR is not null or OTHER_LOAN_TYPE_DESCRIPTION is not null
                     then md5(upper(coalesce(cast(INTEREST_TYPE as varchar), '') || '|' || coalesce(cast(INTEREST_HOLDER_REFERENCE as varchar), '') || '|' || coalesce(cast(LOAN_TENOR as varchar), '') || '|' || coalesce(cast(OTHER_LOAN_TYPE_DESCRIPTION as varchar), '')))
